+import lombok.Builder;
+import lombok.Value;
+import lombok.experimental.SuperBuilder;
+
+@Builder
+public class BuilderDefaultsGenericTypes {
+
+	@Builder.Default
+	String foo = doSth(MyClass.myInt(), MyClass.myChar());
+
+	@Value
+	static class MyClass<T> {
+		T value;
+		static MyClass<Integer> myInt() {
+			return new MyClass<Integer>(42);
+		}
+		static MyClass<Character> myChar() {
+			return new MyClass<Character>('A');
+		}
+	}
+
+	static String doSth(MyClass<Integer> i, MyClass<Character> c) {
+		return i.value.toString() + c.value.toString();
+	}
+
+	public static void main(String[] args) {
+		if (!"42A".equals(BuilderDefaultsGenericTypes.builder().build().foo)) {
+			throw new AssertionError("Wrong builder default");
+		}
+		if (!"custom".equals(BuilderDefaultsGenericTypes.builder().foo("custom").build().foo)) {
+			throw new AssertionError("Builder ignored explicit value");
+		}
+		if (!"42A".equals(SuperBuilderDefaultsGenericTypes.builder().build().foo)) {
+			throw new AssertionError("Wrong super builder default");
+		}
+		if (!"custom".equals(SuperBuilderDefaultsGenericTypes.builder().foo("custom").build().foo)) {
+			throw new AssertionError("Super builder ignored explicit value");
+		}
+	}
+}
+
+@SuperBuilder
+class SuperBuilderDefaultsGenericTypes {
+	@Builder.Default
+	String foo = BuilderDefaultsGenericTypes.doSth(BuilderDefaultsGenericTypes.MyClass.myInt(), BuilderDefaultsGenericTypes.MyClass.myChar());
+}
